from heapq import heappush, heappop


def min_num_taxis(requests):
    taxis = [-1]
    for start, end in sorted(requests):
        if taxis[0] < start:
            heappop(taxis)
        heappush(taxis, end)
    return len(taxis)






if __name__ == '__main__':
